{
  "a_sentences": [
    {
      "a_text": "Die Vorinstanz bestätigte den Einspracheentscheid der Zürich Versicherungs-Gesellschaft AG und verneinte eine über den 3. April 2024 hinausgehende Leistungspflicht für den Unfall vom 22. August 2022 sowie die geltend gemachten Beschwerden.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Vorinstanz begründete die Leistungseinstellung damit, dass ein natürlicher Kausalzusammenhang zwischen dem Ereignis und den Beschwerden fehle, und bewertete den Unfall zudem als leicht, sodass selbst bei einer Prüfung der Adäquanz keine Leistungspflicht bestünde.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Eine Beschwerde an das Bundesgericht muss die Begehren und deren Begründung enthalten und darlegen, inwiefern der angefochtene Akt Recht verletzt, wobei konkret auf die massgeblichen Erwägungen der Vorinstanz einzugehen ist.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Dabei ist im Einzelnen aufzuzeigen, welche Vorschriften die Vorinstanz verletzt hat, und es genügt nicht, die Einstufung der Unfallschwere zu rügen, ohne auf die vorinstanzlichen Erwägungen einzugehen.",
      "b_propositions": ["P4", "P5"]
    },
    {
      "a_text": "Allein die eigene Schilderung des Geschehensablaufs oder die Behauptung, der Entscheid sei falsch, erfüllt die Begründungsanforderungen nicht.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Ohne Bezug zum zusätzlich verneinten natürlichen Kausalzusammenhang bleibt eine solche Kritik unbehelflich.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Die Versicherte legt nicht dar, inwieweit die vorinstanzlichen Sachverhaltsfeststellungen unrichtig sind oder Bundesrecht verletzt wurde.",
      "b_propositions": ["P8"]
    },
    {
      "a_text": "Das Bundesgericht tritt daher auf die Beschwerde nicht ein.",
      "b_propositions": []
    }
  ]
}
